            two_char = expr[i:i+2]
            if two_char in ('==', '!=', '<=', '>=', '&&', '||'):
                tokens.append(('OP', two_char))
                i += 2
                continue

        # Single character operators
        if expr[i] in '()+-*/%<>=!?,':
            tokens.append(('OP', expr[i]))
            i += 1
            continue

        # Numbers (integers and floats)
        if expr[i].isdigit() or (expr[i] == '.' and i + 1 < len(expr) and expr[i+1].isdigit()):
            j = i
            has_dot = False
