        while self.current_token() and self.current_token()[1] == '&&':
            self.consume()  # consume '&&'
            # Short-circuit: only evaluate right if left is true
            if not self._to_bool(left):
                # left is false, result is 0, but we still need to parse the right side
                pass

            right = self.parse_comparison()
            left = 1 if self._to_bool(left) and self._to_bool(right) else 0

        return left

    def parse_comparison(self):
        left = self.parse_additive()

        while True:
            token = self.current_token()
            if token is None or token[0] != 'OP' or token[1] not in ('==', '!=', '<', '<=', '>', '>='):
                break

            op = token[1]
            self.consume()

            right = self.parse_additive()

            if op == '==':
                left = 1 if left == right else 0
            elif op == '!=':
                left = 1 if left != right else 0
            elif op == '<':
                left = 1 if left < right else 0
            elif op == '<=':
                left = 1 if left <= right else 0
            elif op == '>':
                left = 1 if left > right else 0
            elif op == '>=':
                left = 1 if left >= right else 0

        return left

    def parse_additive(self):
        left = self.parse_multiplicative()

        while self.current_token() and self.current_token()[0] == 'OP' and self.current_token()[1] in ('+', '-'):
            op = self.consume()[1]
            right = self.parse_multiplicative()

            if op == '+':
                left = left + right
            else:  # op == '-'
                left = left - right

        return left

    def parse_multiplicative(self):
        left = self.parse_unary()

        while self.current_token() and self.current_token()[0] == 'OP' and self.current_token()[1] in ('*', '/', '%'):
            op = self.consume()[1]
            right = self.parse_unary()

            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result = left / right
                # Return int if exact division of two ints
                if isinstance(left, int) and isinstance(right, int) and result.is_integer():
                    left = int(result)
                else:
                    left = result
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                left = left % right

        return left

    def parse_unary(self):
        token = self.current_token()

        if token and token[0] == 'OP' and token[1] in ('-', '+', '!'):
            op = token[1]
            self.consume()
            operand = self.parse_unary()  # right-associative for unary operators

            if op == '-':
                return -operand
            elif op == '+':
                return operand
            elif op == '!':
                return 1 if operand == 0 else 0

        return self.parse_power()

    def parse_power(self):
        left = self.parse_primary()

        if self.current_token() and self.current_token()[1] == '^':
            self.consume()  # consume '^'
            # Right-associative, so parse the rest as power
            right = self.parse_unary()  # parse_unary to handle 2^-1 correctly
            return left ** right

        return left

    def parse_primary(self):
        token = self.current_token()

        if token is None:
            raise SyntaxError("Unexpected end of expression")

        # Handle parentheses
        if token[0] == 'OP' and token[1] == '(':
            self.consume()
            expr = self.parse_conditional()  # parse full expression inside parentheses
            if self.current_token() is None or self.current_token()[1] != ')':
                raise SyntaxError("Missing closing parenthesis")
            self.consume()
            return expr

        # Handle literals
        if token[0] in ('INT', 'FLOAT'):
            self.consume()
            return token[1]

        # Handle identifiers and function calls
        if token[0] == 'ID':
            name = token[1]
            self.consume()

            # Check if it's a function call
            if self.current_token() and self.current_token()[1] == '(':
                return self.parse_function_call(name)

            # Otherwise it's a variable reference
            if name not in self.env:
                raise NameError(f"Unknown identifier: {name}")
            return self.env[name]

        # Handle lone operators that are invalid
        if token[0] == 'OP' and token[1] in ('=', '&', '|'):
            raise SyntaxError(f"Invalid operator: {token[1]}")

        raise SyntaxError(f"Unexpected token: {token}")

    def parse_function_call(self, name):
        if name not in ('min', 'max', 'abs'):
            raise NameError(f"Unknown function: {name}")

        if self.current_token() is None or self.current_token()[1] != '(':
            raise SyntaxError(f"Expected '(' after function name")

        self.consume()  # consume '('

        args = []
        if self.current_token() and self.current_token()[1] != ')':
            args.append(self.parse_conditional())

            while self.current_token() and self.current_token()[1] == ',':
                self.consume()  # consume ','
                args.append(self.parse_conditional())

        if self.current_token() is None or self.current_token()[1] != ')':
            raise SyntaxError("Missing closing parenthesis in function call")

        self.consume()  # consume ')'

        # Validate argument count
        if name == 'abs':
            if len(args) != 1:
                raise SyntaxError(f"abs() requires exactly 1 argument, got {len(args)}")
            return abs(args[0])
        elif name == 'min':
            if len(args) < 1:
                raise SyntaxError(f"min() requires at least 1 argument")
            result = args[0]
            for arg in args[1:]:
                result = min(result, arg)
            return result
        elif name == 'max':
            if len(args) < 1:
                raise SyntaxError(f"max() requires at least 1 argument")
            result = args[0]
            for arg in args[1:]:
                result = max(result, arg)
            return result

    def _to_bool(self, value):
        return value != 0
