import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        # Ignore empty intervals (start >= end)
        if start >= end:
            return

        # Find the position where the new interval would be inserted
        i = bisect.bisect_left(self._iv, (start, end))

        # Check if we need to merge with the previous interval
        if i > 0 and self._iv[i-1][1] >= start:
            i -= 1

        # Find all intervals that overlap or touch the new interval
        j = i
        while j < len(self._iv) and self._iv[j][0] <= end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1

        # Replace the merged intervals with the new merged interval
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        # Ignore empty intervals (start >= end)
        if start >= end:
            return

        out = []
        for s, e in self._iv:
            # If the current interval doesn't overlap with [start, end), keep it as is
            if e <= start or s >= end:
                out.append((s, e))
                continue

            # If there's a part before [start, end), keep it
            if s < start:
                out.append((s, start))

            # If there's a part after [start, end), keep it
            if e > end:
                out.append((end, e))

        self._iv = out

    def contains(self, x):
        # Find the interval that could contain x
        i = bisect.bisect_left(self._iv, (x, x))

        # Check if the found interval contains x
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True

        # Check if the previous interval contains x (for edge cases)
        if i > 0 and self._iv[i-1][0] <= x < self._iv[i-1][1]:
            return True

        return False

    def free(self, lo, hi):
        # Ignore empty range
        if lo >= hi:
            return []

        gaps = []
        cur = lo

        for s, e in self._iv:
            # If the current interval starts after cur, there's a gap
            if s > cur:
                # Only add the gap if it's within [lo, hi)
                if cur < hi:
                    gaps.append((cur, min(s, hi)))

            # Move cur forward, but don't go beyond hi
            cur = max(cur, e)
            if cur >= hi:
                break

        # If we haven't reached hi yet, there's a final gap
        if cur < hi:
            gaps.append((cur, hi))

        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
