import heapq
from collections import defaultdict

def route(grid: list[str]) -> tuple[int, str] | None:
    # Validate grid
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = len(grid[0])

    # Check for ragged rows
    for row in grid:
        if len(row) != cols:
            raise ValueError("Ragged grid")

    # Count S, E, and validate characters
    s_count = 0
    e_count = 0
    teleport_pads = defaultdict(list)

    for i in range(rows):
        for j in range(cols):
            cell = grid[i][j]
            if cell == 'S':
                s_count += 1
            elif cell == 'E':
                e_count += 1
            elif cell == '#':
                continue
            elif cell == '.':
                continue
            elif cell.isdigit():
                if cell == '0':
                    raise ValueError("Invalid digit '0' in grid")
            elif cell.islower():
                teleport_pads[cell].append((i, j))
            else:
                raise ValueError(f"Unknown character '{cell}' in grid")

    # Check S and E counts
    if s_count != 1:
        raise ValueError(f"Expected exactly one 'S', found {s_count}")
    if e_count != 1:
        raise ValueError(f"Expected exactly one 'E', found {e_count}")

    # Check teleport pads
    for letter, positions in teleport_pads.items():
        if len(positions) != 2:
            raise ValueError(f"Teleport pad '{letter}' appears {len(positions)} times, expected 0 or 2")

    # Find start and end positions
    start = None
    end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Dijkstra's algorithm with lexicographic tie-breaking
    # Priority queue: (cost, moves_string, row, col)
    # moves_string is used for lexicographic ordering

    # Directions: D, L, R, T, U (in lexicographic order as required)
    # But note: T is special (teleport), so we handle it separately

    # For regular moves: D, L, R, U (in that order for lexicographic comparison)
    # But the problem says: D < L < R < T < U, so we need to process in that order

    # We'll use a priority queue where the priority is (cost, moves_string)
    # Since moves_string comparison is lexicographic, and we want D < L < R < T < U,
    # we need to make sure our moves are generated in the right order

    # Actually, to ensure lexicographically smallest string among same cost paths,
    # we need to process moves in lexicographic order (D, L, R, T, U)

    # But Dijkstra with priority queue: we process states in order of (cost, moves)
    # So we need to push moves in lexicographic order

    # Directions with their move characters and costs
    # Regular moves: (dr, dc, move_char, cost)
    regular_moves = [
        (1, 0, 'D', 1),   # Down
        (0, -1, 'L', 1),  # Left
        (0, 1, 'R', 1),   # Right
        (-1, 0, 'U', 1)   # Up
    ]

    # Teleport move: handled separately

    # Initialize distance and path arrays
    # dist[i][j] = (min_cost, best_moves_string) to reach (i,j)
    dist = {}
    # Use a dictionary for dist: dist[(i,j)] = (cost, moves)

    # Priority queue: (cost, moves, i, j)
    pq = []

    # Start position
    start_i, start_j = start
    dist[(start_i, start_j)] = (1, "")  # S costs 1
    heapq.heappush(pq, (1, "", start_i, start_j))

    # Process states
    while pq:
        cost, moves, i, j = heapq.heappop(pq)

        # Skip if we've found a better path to this cell already
        if (i, j) in dist and dist[(i, j)] < (cost, moves):
            continue

        # Check if we reached the end
        if (i, j) == end:
            return (cost, moves)

        # Try regular moves (D, L, R, U in that order for lexicographic preference)
        for dr, dc, move_char, move_cost in regular_moves:
            ni, nj = i + dr, j + dc
            if 0 <= ni < rows and 0 <= nj < cols:
                cell = grid[ni][nj]
                if cell == '#':
                    continue

                # Calculate new cost
                if cell == 'S' or cell == 'E' or cell == '.':
                    new_cost = cost + 1
                elif cell.isdigit():
                    new_cost = cost + int(cell)
                elif cell.islower():
                    new_cost = cost + 1  # Pad costs 1
                else:
                    continue

                new_moves = moves + move_char

                # Check if this is a better path
                if (ni, nj) not in dist or (new_cost, new_moves) < dist[(ni, nj)]:
                    dist[(ni, nj)] = (new_cost, new_moves)
                    heapq.heappush(pq, (new_cost, new_moves, ni, nj))

        # Try teleport move (T) if current cell is a teleport pad
        cell = grid[i][j]
        if cell.islower():
            # Find the other teleport pad with the same letter
            positions = teleport_pads[cell]
            for pos in positions:
                if pos != (i, j):
                    ti, tj = pos
                    # Teleport costs 2
                    new_cost = cost + 2
                    new_moves = moves + 'T'

                    # Check if this is a better path
                    if (ti, tj) not in dist or (new_cost, new_moves) < dist[(ti, tj)]:
                        dist[(ti, tj)] = (new_cost, new_moves)
                        heapq.heappush(pq, (new_cost, new_moves, ti, tj))

    # If we exit the loop without finding the end, it's unreachable
    return None
