def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()
    result = {}
    current_section = ""
    current_key = None
    continuation_value = None
    continuation_section = None

    # First pass: parse the INI content
    for line_num, line in enumerate(lines, 1):
        # Skip empty lines
        if not line.strip():
            # End continuation if we were in one
            if continuation_value is not None:
                # Store the accumulated value
                if continuation_section not in result:
                    result[continuation_section] = {}
                result[continuation_section][current_key] = continuation_value
                continuation_value = None
                current_key = None
                continuation_section = None
            continue

        # Check for comment lines (lines starting with # or ; after optional whitespace)
        stripped = line.lstrip()
        if stripped.startswith('#') or stripped.startswith(';'):
            continue

        # Check for continuation line (starts with whitespace and we have a current entry)
        if line[0].isspace() and continuation_value is not None:
            # Trim the continuation line and append with newline
            continuation_value += '\n' + line.strip()
            continue

        # End continuation if we were in one
        if continuation_value is not None:
            # Store the accumulated value
            if continuation_section not in result:
                result[continuation_section] = {}
            result[continuation_section][current_key] = continuation_value
            continuation_value = None
            current_key = None
            continuation_section = None

        # Check for section header
        if stripped.startswith('['):
            # Find closing bracket
            end_bracket = stripped.find(']')
            if end_bracket == -1:
                raise ValueError(f"line {line_num}: unclosed '['")

            section_name = stripped[1:end_bracket].strip()
            current_section = section_name
            continue

        # Check for key=value or key:value
        # Find first = or : separator
        eq_pos = stripped.find('=')
        colon_pos = stripped.find(':')

        # Determine separator position
        if eq_pos == -1 and colon_pos == -1:
            raise ValueError(f"line {line_num}: missing separator")

        # Use the first separator found
        if eq_pos == -1:
            sep_pos = colon_pos
        elif colon_pos == -1:
            sep_pos = eq_pos
        else:
            sep_pos = min(eq_pos, colon_pos)

        # Extract key and value parts
        key_part = stripped[:sep_pos].strip()
        value_part = stripped[sep_pos+1:].strip()

        # Handle inline comments (but not inside quotes)
        if value_part:
            # Find comment markers outside of quotes
            in_quotes = False
            comment_pos = -1
            i = 0
            while i < len(value_part):
                if value_part[i] == '"' and (i == 0 or value_part[i-1] != '\\'):
                    in_quotes = not in_quotes
                elif not in_quotes and (value_part[i] == ';' or value_part[i] == '#'):
                    # Check if there's whitespace before the comment marker
                    if i > 0 and value_part[i-1].isspace():
                        comment_pos = i
                        break
                i += 1

            if comment_pos != -1:
                value_part = value_part[:comment_pos].strip()

        # Handle quoted values
        if value_part.startswith('"') and value_part.endswith('"') and len(value_part) >= 2:
            # Remove quotes and handle escaped quotes
            inner = value_part[1:-1]
            # Replace \" with "
            value_part = inner.replace('\\"', '"')
        elif value_part.startswith('"'):
            # Unclosed quote
            raise ValueError(f"line {line_num}: unterminated quote")

        # Store the key-value pair
        key = key_part.lower()

        # Start continuation if needed
        continuation_value = value_part
        continuation_section = current_section
        current_key = key

    # Handle any remaining continuation
    if continuation_value is not None:
        if continuation_section not in result:
            result[continuation_section] = {}
        result[continuation_section][current_key] = continuation_value

    # Remove empty section if it has no keys
    if "" in result and len(result[""]) == 0:
        del result[""]

    # Second pass: perform interpolation
    def interpolate(value: str, section: str, visited: set) -> str:
        if value is None:
            return ""

        result_parts = []
        i = 0
        while i < len(value):
            if value[i:i+2] == '$$':
                result_parts.append('$')
                i += 2
            elif value[i:i+2] == '${':
                # Find closing brace
                end_pos = value.find('}', i+2)
                if end_pos == -1:
                    raise ValueError(f"line 0: unclosed interpolation")

                ref = value[i+2:end_pos]
                i = end_pos + 1

                # Parse reference
                if ':' in ref:
                    parts = ref.split(':', 1)
                    ref_section = parts[0].strip()
                    ref_key = parts[1].strip().lower()
                else:
                    ref_section = section
                    ref_key = ref.strip().lower()

                # Check for cycle
                current_ref = (ref_section, ref_key)
                if current_ref in visited:
                    raise ValueError(f"line 0: interpolation cycle detected")

                # Get referenced value
                if ref_section not in result or ref_key not in result[ref_section]:
                    raise ValueError(f"line 0: undefined reference ${ref}")

                # Recursively interpolate
                new_visited = visited | {current_ref}
                ref_value = interpolate(result[ref_section][ref_key], ref_section, new_visited)
                result_parts.append(ref_value)
            else:
                result_parts.append(value[i])
                i += 1

        return ''.join(result_parts)

    # Create a copy to avoid modifying during iteration
    final_result = {}
    for section in result:
        final_result[section] = {}
        for key in result[section]:
            try:
                final_result[section][key] = interpolate(result[section][key], section, set())
            except ValueError as e:
                if "cycle" not in str(e).lower():
                    raise ValueError(f"line 0: {e}")
                else:
                    raise

    return final_result
