import re
from functools import total_ordering
from typing import List, Optional, Tuple, Union


@total_ordering
class Version:
    def __init__(self, version_str: str):
        self.original = version_str
        self._parse(version_str)

    def _parse(self, version_str: str):
        # Remove leading 'v' or '='
        s = version_str.strip()
        if s.startswith('v') or s.startswith('='):
            s = s[1:]
        s = s.strip()

        # Parse version string
        # Format: MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        # We need to handle build metadata separately
        build_metadata = None
        if '+' in s:
            s, build_metadata = s.split('+', 1)
            if not build_metadata:
                raise ValueError("Invalid version: empty build metadata")

        # Parse prerelease
        prerelease = None
        if '-' in s:
            s, prerelease = s.split('-', 1)
            if not prerelease:
                raise ValueError("Invalid version: empty prerelease")

        # Parse main version parts
        parts = s.split('.')
        if len(parts) < 1 or len(parts) > 3:
            raise ValueError("Invalid version: must have 1-3 version parts")

        # Validate and parse each part
        self.major = self._parse_numeric_part(parts[0], "major")
        self.minor = self._parse_numeric_part(parts[1], "minor") if len(parts) > 1 else 0
        self.patch = self._parse_numeric_part(parts[2], "patch") if len(parts) > 2 else 0

        # Parse prerelease identifiers
        if prerelease is not None:
            self.prerelease = self._parse_prerelease(prerelease)
        else:
            self.prerelease = []

        # Store build metadata as string
        self.build_metadata = build_metadata

    def _parse_numeric_part(self, part: str, name: str) -> int:
        if not part:
            raise ValueError(f"Invalid version: empty {name} part")
        # Check for leading zeros (except for "0" itself)
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Invalid version: leading zeros in {name} part")
        try:
            return int(part)
        except ValueError:
            raise ValueError(f"Invalid version: {name} part is not numeric")

    def _parse_prerelease(self, prerelease_str: str) -> List[Union[int, str]]:
        identifiers = prerelease_str.split('.')
        result = []
        for identifier in identifiers:
            if not identifier:
                raise ValueError("Invalid version: empty prerelease identifier")
            # Check identifier format: [0-9A-Za-z-]+
            if not re.match(r'^[0-9A-Za-z-]+$', identifier):
                raise ValueError(f"Invalid version: invalid prerelease identifier '{identifier}'")
            # Try to parse as numeric
            if re.match(r'^[0-9]+$', identifier):
                # Numeric identifier
                if len(identifier) > 1 and identifier[0] == '0':
                    raise ValueError(f"Invalid version: leading zeros in numeric prerelease identifier '{identifier}'")
                result.append(int(identifier))
            else:
                # Alphanumeric identifier
                result.append(identifier)
        return result

    def _compare_prerelease(self, other: 'Version') -> int:
        # A version without prerelease is greater than one with prerelease
        if not self.prerelease and other.prerelease:
            return 1
        if self.prerelease and not other.prerelease:
            return -1
        if not self.prerelease and not other.prerelease:
            return 0

        # Compare identifier by identifier
        for i in range(min(len(self.prerelease), len(other.prerelease))):
            a = self.prerelease[i]
            b = other.prerelease[i]
            # Numeric vs numeric
            if isinstance(a, int) and isinstance(b, int):
                if a < b:
                    return -1
                elif a > b:
                    return 1
            # Numeric vs alphanumeric: numeric is smaller
            elif isinstance(a, int) and isinstance(b, str):
                return -1
            elif isinstance(a, str) and isinstance(b, int):
                return 1
            # Alphanumeric vs alphanumeric: ASCII order
            else:
                if a < b:
                    return -1
                elif a > b:
                    return 1

        # If all compared identifiers are equal, shorter list is smaller
        if len(self.prerelease) < len(other.prerelease):
            return -1
        elif len(self.prerelease) > len(other.prerelease):
            return 1
        return 0

    def __eq__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return False
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __lt__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        return self._compare_prerelease(other) < 0

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))

    def __repr__(self):
        return f"Version({self.original!r})"


def parse(version_str: str) -> Version:
    return Version(version_str)


def _parse_partial_version(version_str: str) -> Tuple[int, int, int, bool]:
    """Parse a partial version string into (major, minor, patch, has_minor, has_patch)"""
    s = version_str.strip()
