        s = s[1:]
    s = s.strip()

    # Handle X-ranges
    if s == '*' or s.lower() == 'x':
        return (0, 0, 0, True, True)

    parts = s.split('.')
    if len(parts) > 3:
        raise ValueError(f"Invalid partial version: too many parts")

    major = 0
    minor = 0
    patch = 0
    has_minor = False
    has_patch = False

    # Parse major
    if parts[0] == '*' or parts[0].lower() == 'x':
        major = 0
        has_minor = True
        has_patch = True
    else:
        major = int(parts[0])
        if len(parts[0]) > 1 and parts[0][0] == '0':
            raise ValueError(f"Invalid partial version: leading zeros in major part")
        has_minor = len(parts) > 1
        has_patch = len(parts) > 2

    # Parse minor
    if has_minor and len(parts) > 1:
        if parts[1] == '*' or parts[1].lower() == 'x':
            has_patch = True
        else:
            minor = int(parts[1])
            if len(parts[1]) > 1 and parts[1][0] == '0':
                raise ValueError(f"Invalid partial version: leading zeros in minor part")
            has_patch = len(parts) > 2

    # Parse patch
    if has_patch and len(parts) > 2:
        if parts[2] == '*' or parts[2].lower() == 'x':
            pass  # patch is wildcard
        else:
            patch = int(parts[2])
            if len(parts[2]) > 1 and parts[2][0] == '0':
                raise ValueError(f"Invalid partial version: leading zeros in patch part")

    return (major, minor, patch, has_minor, has_patch)


def _create_version_from_partial(major: int, minor: int, patch: int, prerelease: Optional[List] = None) -> Version:
    """Create a Version object from partial components"""
    v = Version.__new__(Version)
    v.major = major
    v.minor = minor
    v.patch = patch
    v.prerelease = prerelease if prerelease is not None else []
    v.build_metadata = None
    v.original = f"{major}.{minor}.{patch}"
    return v


def _parse_comparator(range_str: str) -> Tuple[str, Version]:
    """Parse a comparator like '>1.2.3' into ('>', Version('1.2.3'))"""
    s = range_str.strip()

    # Extract operator
    op = ''
    if s.startswith('>='):
        op = '>='
        s = s[2:]
    elif s.startswith('<='):
        op = '<='
        s = s[2:]
    elif s.startswith('>'):
        op = '>'
        s = s[1:]
    elif s.startswith('<'):
        op = '<'
        s = s[1:]
    elif s.startswith('=') and not s.startswith('=='):
        op = '='
        s = s[1:]
    else:
        op = '='  # Default operator is '='

    # Parse version
    version_str = s.strip()
    if not version_str:
        raise ValueError("Invalid comparator: missing version")

    return op, parse(version_str)


def _satisfies_partial(version: Version, major: int, minor: int, patch: int, has_minor: bool, has_patch: bool) -> bool:
    """Check if version satisfies a partial version constraint"""
    if version.major != major:
        return False
    if has_minor and version.minor != minor:
        return False
    if has_patch and version.patch != patch:
        return False
    return True


def _satisfies_comparator(version: Version, op: str, comparator_version: Version) -> bool:
    """Check if version satisfies a comparator"""
    if op == '=':
        return version == comparator_version
    elif op == '>':
        return version > comparator_version
    elif op == '<':
        return version < comparator_version
    elif op == '>=':
        return version >= comparator_version
    elif op == '<=':
        return version <= comparator_version
    else:
        raise ValueError(f"Invalid operator: {op}")


def _parse_range_set(range_str: str) -> List[Tuple]:
    """Parse a single comparator set (whitespace-separated comparators)"""
    parts = range_str.split()
    if not parts or parts == ['*']:
        return [('wildcard',)]

    comparators = []
    for part in parts:
        if not part:
            continue
        op, version = _parse_comparator(part)
        comparators.append((op, version))

    if not comparators:
        raise ValueError("Invalid range: empty comparator set")

    return comparators


def _parse_range(range_str: str) -> List[List[Tuple]]:
    """Parse a full range string into list of comparator sets"""
    # Split by ||
    sets_str = range_str.split('||')
    sets = []
    for set_str in sets_str:
        set_str = set_str.strip()
        if not set_str:
            raise ValueError("Invalid range: empty comparator set")
        set_comparators = _parse_range_set(set_str)
        sets.append(set_comparators)

    return sets


def _satisfies_set(version: Version, comparators: List[Tuple]) -> bool:
    """Check if version satisfies a comparator set"""
    # Handle wildcard
    if comparators[0][0] == 'wildcard':
        return True

    # Check all comparators
    for comparator in comparators:
        if comparator[0] == 'wildcard':
            continue
        op, comp_version = comparator
        if not _satisfies_comparator(version, op, comp_version):
            return False

    return True


def _satisfies_prerelease(version: Version, comparators: List[Tuple]) -> bool:
    """Check prerelease compatibility: if version has prerelease, at least one comparator must have same MAJOR.MINOR.PATCH with prerelease"""
    if not version.prerelease:
        return True

    # Check if any comparator has same MAJOR.MINOR.PATCH with prerelease
    for comparator in comparators:
        if comparator[0] == 'wildcard':
            continue
        op, comp_version = comparator
        if (comp_version.major == version.major and
            comp_version.minor == version.minor and
            comp_version.patch == version.patch and
            comp_version.prerelease):
            return True

    return False


def satisfies(version_str: str, range_str: str) -> bool:
    version = parse(version_str)
    range_sets = _parse_range(range_str)

    # Check if version satisfies any set
    for set_comparators in range_sets:
        if _satisfies_set(version, set_comparators) and _satisfies_prerelease(version, set_comparators):
            return True

    return False


def max_satisfying(versions: List[str], range_str: str) -> Optional[str]:
    if not versions:
        return None

    # Parse all versions
    parsed_versions = []
    for v in versions:
        try:
            parsed_versions.append((parse(v), v))
        except ValueError:
            # Skip invalid versions
            continue

    if not parsed_versions:
        return None

    # Filter versions that satisfy the range
    satisfying_versions = []
    for version_obj, original_str in parsed_versions:
        if satisfies(original_str, range_str):
            satisfying_versions.append((version_obj, original_str))

    if not satisfying_versions:
        return None

    # Return the maximum version (by SemVer precedence)
    max_version = max(satisfying_versions, key=lambda x: x[0])
    return max_version[1]
