        # Double quoted value
        i = 2
        while (i <= len) {
            c = substr(value_part, i, 1)
            if (c == "\\") {
                # Escape sequence
                if (i < len) {
                    next_c = substr(value_part, i+1, 1)
                    if (next_c == "n") {
                        value = value "\n"
                        i += 2
                    } else if (next_c == "\"") {
                        value = value "\""
                        i += 2
                    } else if (next_c == "\\") {
                        value = value "\\"
                        i += 2
                    } else {
                        # Other escape sequences stay as is
                        value = value c next_c
                        i += 2
                    }
                } else {
                    # Trailing backslash
                    value = value c
                    i++
                }
            } else if (c == "\"") {
                # End of double quoted string
                i++
                break
            } else {
                value = value c
                i++
            }
        }
        # Check remaining characters after closing quote
        rest = substr(value_part, i)
        gsub(/^[[:space:]]+/, "", rest)
        if (rest != "" && substr(rest, 1, 1) != "#") {
            print FILENAME ":" line_num ": invalid line" > "/dev/stderr"
            error_occurred = 1
            exit 1
        }
    }
    # Unquoted value
    else {
        # Find unquoted comment (space followed by #)
        # But be careful: a#b should keep the hash
        # Only space followed by # starts a comment
        j = 1
        while (j <= len) {
            c = substr(value_part, j, 1)
            if (c == " " && substr(value_part, j+1, 1) == "#") {
                # Found comment start
                break
            }
            value = value c
            j++
        }
        # Trim trailing spaces and tabs
        gsub(/[[:space:]]+$/, "", value)
    }

    # Store the key-value pair (later values overwrite earlier ones)
    keys[key] = value
    # Track order of first occurrence for output
    if (!(key in seen)) {
        order[++order_count] = key
        seen[key] = 1
    }
}

END {
    if (error_occurred) {
        exit 1
    }

    # Output in order of first occurrence
    for (i = 1; i <= order_count; i++) {
        key = order[i]
        value = keys[key]

        # Escape single quotes in value: '\'' 
        # Replace ' with '\'' 
        gsub(/'\''/, "'\''\\'\'''\''", value)

        # Output: export KEY='<value>'
        printf "export %s='\''%s'\''\n", key, value
    }
}
' "$FILE"

exit $?
